toolArgs.file_text:
@page "/recipes/{CategorySlug}/{RecipeSlug}"

<PageTitle>@(GetRecipe()?.Title ?? "Recipe") - RecipeHub</PageTitle>

<p><a href="/recipes/@CategorySlug">← Back to @CategorySlug</a></p>

@if (GetRecipe() is { } recipe)
{
    <h1>@recipe.Title</h1>
    <p class="recipe-description">@recipe.Description</p>

    <StarRating RecipeName="@recipe.Title" @rendermode="Microsoft.AspNetCore.Components.Web.RenderMode.InteractiveServer" />

    <h2>Ingredients</h2>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li>@step</li>
        }
    </ol>
}
else
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}

@code {
    [Parameter] public string CategorySlug { get; set; } = "";
    [Parameter] public string RecipeSlug { get; set; } = "";

    private RecipeDetail? GetRecipe() => (CategorySlug, RecipeSlug) switch
    {
        ("breakfast", "fluffy-pancakes") => new(
            "Fluffy Pancakes",
            "Classic buttermilk pancakes that are light and airy — perfect for a weekend brunch.",
            new[] { "2 cups all-purpose flour", "2 tbsp sugar", "1 tbsp baking powder", "1/2 tsp salt", "2 eggs", "1 1/2 cups buttermilk", "1/4 cup melted butter" },
            new[] { "Mix dry ingredients in a large bowl.", "Whisk eggs, buttermilk, and melted butter separately.", "Combine wet and dry ingredients — don't overmix.", "Heat a griddle to medium and grease lightly.", "Pour 1/4 cup batter per pancake. Cook until bubbles form, then flip.", "Serve with maple syrup and fresh berries." }
        ),
        ("breakfast", "avocado-toast") => new(
            "Avocado Toast",
            "Creamy avocado on crispy sourdough bread with a perfect seasoning blend.",
            new[] { "2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper", "Red pepper flakes", "Optional: poached egg" },
            new[] { "Toast the sourdough until golden and crispy.", "Halve the avocado, remove pit, scoop into a bowl.", "Mash with lemon juice, salt, and pepper.", "Spread onto toast and sprinkle with red pepper flakes.", "Top with a poached egg if desired." }
        ),
        ("breakfast", "berry-smoothie-bowl") => new(
            "Berry Smoothie Bowl",
            "A vibrant blend of mixed berries and yogurt topped with granola and fresh fruit.",
            new[] { "1 cup frozen mixed berries", "1 banana", "1/2 cup Greek yogurt", "1/4 cup almond milk", "Granola", "Fresh berries and sliced banana for topping" },
