@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="star @(star <= CurrentRating ? "filled" : "")"
                @onclick="() => SetRating(star)"
                title="@star star(s)">
            @(star <= CurrentRating ? "★" : "☆")
        </button>
    }
    @if (CurrentRating > 0)
    {
        <span class="rating-text">You rated this @CurrentRating/5</span>
    }
</div>

@code {
    [Parameter] public string RecipeName { get; set; } = "";

    private int CurrentRating { get; set; }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
    }
}

